Mesh<Point, double> mesh;
std::vector<std::pair<Point, Point>> edges;
std::vector<double> face_areas;

for (auto f = rt.finite_facets_begin(); f != rt.finite_facets_end(); ++f) {
    if (!is_large_facet(rt, *f, threshold)) {
        continue;
    }

    RT::Cell_handle c = f->first;
    unsigned k = f->second;
    RT::Cell_handle n = c->neighbor(k);

    Point dual_c = rt.dual(c);
    Point dual_n = rt.dual(n);

    edges.emplace_back(dual_c, dual_n);
    face_areas.push_back(rt.triangle(c, k).squared_area());
}

mesh.add_edges(edges.begin(), edges.end());
mesh.add_face_data(face_areas.begin(), face_areas.end());
return mesh;

